# =============================================================================
# LOD 300 Structural Model — Phase 3: Schedule-Aware Layout
# Generated by pipeline_phase3.py — hybrid schedule + plan-text detection
# =============================================================================

model  = Sketchup.active_model
model.name        = "LOD300 Structural Model Phase3"
model.description = "Schedule-aware per-floor structural model"
ents   = model.active_entities
layers = model.layers
model.start_operation('LOD300 Phase3 Import', true)

def get_or_create_layer(layers, name)
  layers[name] || layers.add(name)
end

# ── Layers ──
["STR-Columns", "STR-Beams", "STR-Braces", "STR-Plates", "STR-Walls", "STR-Slabs", "STR-Foundations", "LOD300_UNMAPPED_NEEDS_REVIEW"].each do |lname|
  get_or_create_layer(layers, lname)
end

# ── Materials ──
_mats = model.materials
_steel_mat = _mats["Structural_Steel"] || _mats.add("Structural_Steel")
_steel_mat.color = Sketchup::Color.new(160, 160, 175)
_concrete_mat = _mats["Concrete"] || _mats.add("Concrete")
_concrete_mat.color = Sketchup::Color.new(180, 175, 165)

# ============================================================
# FLOOR: Level 1 (Z: 0 → 3500 mm)
# ============================================================

# ---- GC_0_0 | 300x300 | column | Level 1 ----
begin
  _sp  = Geom::Point3d.new(4000.0.mm, 0.0.mm, 0.0.mm)
  _ep  = Geom::Point3d.new(4000.0.mm, 0.0.mm, 3500.0.mm)
  _vec = _sp.vector_to(_ep)
  _len = _sp.distance(_ep)
  if _len < 1.mm || !_vec.valid?
    puts "SKIP GC_0_0: zero-length (check mapper coords)"
  else
    _grp = ents.add_group
    _ge  = _grp.entities
    _t   = Geom::Transformation.new(_sp, _vec)
    _raw = [[-150.0, -150.0], [150.0, -150.0],
            [150.0, 150.0], [-150.0, 150.0]]
    _face = _ge.add_face(_raw.map { |p| _t * Geom::Point3d.new(p[0].mm, p[1].mm, 0) })
    _face.pushpull(_len) if _face
    _grp.layer = get_or_create_layer(layers, "STR-Columns")
    _grp.material = _concrete_mat
    _grp.set_attribute("IFC", "Mark",    "GC_0_0")
    _grp.set_attribute("IFC", "Section", "300x300")
    _grp.set_attribute("IFC", "Type",    "column")
    _grp.name = "GC_0_0"
  end
rescue => e
  puts "SKIP GC_0_0: #{e.message}"
end

